pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address addr, uint256 value) public {
        // Bound value to prevent DoS (but allow overflow to be detected)
        vm.assume(value > 0);
        value = bound(value, 1, 1e18);

        // Get initial balance of contract
        uint256 initialBalance = address(c).balance;

        // Get initial user balance
        uint256 userBalBefore = c.getBalance(addr);

        // Get initial sum of all balances (only addr has non-zero balance)
        uint256 sumBefore = userBalBefore;

        // Send Ether to addToBalance (uses msg.sender = addr via prank)
        vm.deal(addr, value);
        vm.prank(addr);
        c.addToBalance{value: value}();

        // Check: total contract balance should equal sum of user balances + initial balance
        // The sum of user balances after = getBalance(addr) + (any other non-zero balances, assume only addr)
        uint256 userBalAfter = c.getBalance(addr);
        uint256 sumAfter = userBalAfter;
        uint256 contractBalAfter = address(c).balance;

        // Rule: contract balance == sum of user balances + initialBalance
        // In reference, this holds. In mutant with overflow, user balance may wrap, breaking equality
        assertTrue(contractBalAfter == sumAfter + initialBalance, "Invariant violation: contract balance mismatch");
    }
}

