pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address user, uint256 value) public {
        vm.assume(value <= type(uint256).max - 10); // ensure enough room for old balance plus value
        vm.assume(user != address(0));

        // Pre-state: set initial balance for user
        vm.deal(user, 1 ether);
        vm.prank(user);
        (bool success, ) = address(c).call{value: 0}(""); // just to have some balance

        uint256 oldBalance = c.getBalance(user);

        // Drive addToBalance with enough ether
        vm.deal(user, value);
        vm.prank(user);
        c.addToBalance{value: value}();

        // Rule: new balance == old balance + value
        uint256 newBalance = c.getBalance(user);
        assertTrue(newBalance == oldBalance + value, "Balance should be sum, not overflow-truncated");
    }
}

