pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address sender, uint256 value) public {
        vm.assume(sender != address(0));
        vm.assume(value <= type(uint256).max - 1); // avoid overflow in known good case
        vm.deal(sender, value);
        vm.prank(sender);
        uint256 balanceBefore = c.getBalance(sender);
        // Ensure no overflow would occur in reference
        vm.assume(balanceBefore + value >= balanceBefore);
        c.addToBalance{value: value}();
        uint256 balanceAfter = c.getBalance(sender);
        assertTrue(balanceAfter == balanceBefore + value, "Overflow protection failed");
    }
}

